#!/usr/bin/env python
import argparse
import os
from multiprocessing import Process, Queue

from taf.sw.syslog.cli_tools.listener import Listener
from taf.sw.syslog.cli_tools.logger import SyslogLogger


def parse_arguments(argv):
    """Provide a command line interface and parse provided arguments."""
    parser = argparse.ArgumentParser(description="Script to start syslog gathering")
    parser.add_argument(
        "-d", help="Directory where to store the log", dest="log_dir", required=True
    )
    parser.add_argument("-l", help="Log file name", dest="log_name", required=True)
    parser.add_argument("-i", help="IP address to bind", dest="ip", default="0.0.0.0")
    parser.add_argument(
        "-p", help="Ports to bind", nargs="+", dest="ports", type=int, default=None
    )
    parser.add_argument(
        "-s", help="Log size limit", dest="file_limit", type=int, default=0
    )
    parser.add_argument(
        "-a",
        "--addLineNumbers",
        help="Add line numbers",
        dest="add_line_number",
        action="store_true",
    )
    return parser.parse_args(argv)


def start_logger(args, queue: Queue):
    """
    Create a logger instance.

    :param args: Information provided by the user as argparse arguments.
    :param queue: Queue instance that the logger should consume
    """
    logger = SyslogLogger(
        queue=queue,
        log_dir=args.log_dir,
        log_name=args.log_name,
        file_size_limit=args.file_limit,
        add_line_number=args.add_line_number,
    )
    logger.clean_log_file()
    logger_process = Process(name="syslog_logger", target=logger.run)
    logger_process.start()
    return logger_process.pid


def start_listeners(args, queue: Queue):
    """
    Create a listener for each specified port and start it.

    :param args: Information provided by the user as argparse arguments
    :param queue: Queue instance that the listeners should put data into
    """
    ports = [int(port) for port in args.ports]
    pids = []

    for port in ports:
        listener = Listener(args.ip, port, queue)
        listener_process = Process(name=f"UDP_listener_{port}", target=listener.run)
        listener_process.start()
        pids.append(listener_process.pid)

    return pids


def main(argv=None):

    args = parse_arguments(argv)
    master_pid = os.getpid()
    queue = Queue()
    logger_pid = start_logger(args, queue)
    listener_pids = start_listeners(args, queue)
    pids = " ".join([str(master_pid), str(logger_pid), *map(str, listener_pids)])
    print(f"Syslog PIDs: {pids}")  # noqa: T201
    print("Syslog started!")  # noqa: T201


if __name__ == "__main__":
    main()
